def prepare_prompt(description, previous_tweets, tweet_to_classify):
    """
    Prepares a prompt for classification by listing tweets clearly and asking for a response.
    This function now processes only one tweet at a time.
    """
    prompt = (
        f"User Description:\n{description}\n\n"
        f"Previous Tweets:\n{', '.join(previous_tweets)}\n\n"
        f"Tweet to Classify:\n{tweet_to_classify}\n\n"
        "Task:\nBased on the description and the previous tweets of the user, "
        "output '0' if the above tweet was not generated by the user or '1' if it was. "
        "Even if the tweet is a URL, output '0' or '1' as your response."
    )
    return prompt
